"""Create local-only configuration without overwriting existing values."""

import os
import secrets
from pathlib import Path
from urllib.parse import quote

ROOT = Path(__file__).resolve().parents[1]


def read_values(path: Path) -> dict[str, str]:
    """Read the simple unquoted KEY=value format generated by this script."""
    if not path.exists():
        return {}
    return dict(
        line.split("=", 1)
        for line in path.read_text().splitlines()
        if line and not line.startswith("#") and "=" in line
    )


def add_missing(path: Path, values: dict[str, str]) -> None:
    existing = read_values(path)
    missing = {key: value for key, value in values.items() if key not in existing}
    if missing:
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
        with os.fdopen(descriptor, "a", encoding="utf-8") as stream:
            stream.write("\n")
            stream.writelines(f"{key}={value}\n" for key, value in missing.items())
        path.chmod(0o600)


def main() -> None:
    compose_path = ROOT / ".env.compose"
    add_missing(compose_path, {"POSTGRES_PASSWORD": secrets.token_hex(24)})
    password = quote(read_values(compose_path)["POSTGRES_PASSWORD"], safe="")
    add_missing(
        ROOT / ".env",
        {
            "QUEUEPILOT_ENVIRONMENT": "development",
            "QUEUEPILOT_DATABASE_URL": (
                f"postgresql+psycopg://queuepilot:{password}@127.0.0.1:55432/queuepilot"
            ),
            "QUEUEPILOT_REDIS_URL": "redis://127.0.0.1:56379/0",
        },
    )
    add_missing(
        ROOT / ".env.test",
        {
            "QUEUEPILOT_TEST_DATABASE_URL": (
                f"postgresql+psycopg://queuepilot_test:{password}"
                "@127.0.0.1:55433/queuepilot_test"
            ),
            "QUEUEPILOT_TEST_REDIS_URL": "redis://127.0.0.1:56380/0",
        },
    )
    print("Local config prepared; existing values preserved. No credentials printed.")


if __name__ == "__main__":
    main()
